import{_ as i,o as a,c as e,a3 as t}from"./chunks/framework.fntC-tS-.js";const k=JSON.parse('{"title":"Linux 桌面应用界面变大:原因排查与修复","description":"","frontmatter":{},"headers":[],"relativePath":"Linux系统/LINUX桌面应用界面变大原因和修复.md","filePath":"Linux系统/LINUX桌面应用界面变大原因和修复.md","lastUpdated":1793939301000}'),l={name:"Linux系统/LINUX桌面应用界面变大原因和修复.md"};function n(d,s,h,p,o,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="linux-桌面应用界面变大-原因排查与修复" tabindex="-1">Linux 桌面应用界面变大:原因排查与修复 <a class="header-anchor" href="#linux-桌面应用界面变大-原因排查与修复" aria-label="Permalink to &quot;Linux 桌面应用界面变大:原因排查与修复&quot;">​</a></h1><h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h2><p>在 Linux(KDE + X11)上,用 Rust 写的 GUI 应用(基于 GPUI 的 Pure Clash,以及一个 Rust + Slint 应用)启动后界面整体放大,窗口尺寸没变,内容被截断、卡片文字重叠。</p><p>环境:</p><ul><li>会话类型:X11(<code>echo $XDG_SESSION_TYPE</code> 输出 <code>x11</code>)</li><li>桌面环境:KDE</li><li>显卡:NVIDIA(启动时有无害的 <code>libEGL warning</code>)</li><li><code>xdpyinfo</code> 显示 DPI 为 92x94,看起来正常</li></ul><h2 id="排查过程" tabindex="-1">排查过程 <a class="header-anchor" href="#排查过程" aria-label="Permalink to &quot;排查过程&quot;">​</a></h2><h3 id="_1-先排除无关的东西" tabindex="-1">1. 先排除无关的东西 <a class="header-anchor" href="#_1-先排除无关的东西" aria-label="Permalink to &quot;1. 先排除无关的东西&quot;">​</a></h3><ul><li><strong><code>libEGL warning: ... failed to create dri2 screen</code></strong>:Mesa 的 EGL 在 NVIDIA 显卡上尝试 dri2 驱动失败,随后回退到 NVIDIA 驱动,和缩放无关,可以忽略。</li><li><strong><code>GDK_SCALE</code> / <code>GDK_DPI_SCALE</code></strong>:这是 GTK 的变量,GPUI 和 Slint 都不用 GTK,设了没有效果。</li><li><strong><code>WAYLAND_DISPLAY=</code></strong>:本来就是 X11 会话,强制走 X11 没有意义。</li></ul><h3 id="_2-逐层检查系统缩放来源" tabindex="-1">2. 逐层检查系统缩放来源 <a class="header-anchor" href="#_2-逐层检查系统缩放来源" aria-label="Permalink to &quot;2. 逐层检查系统缩放来源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>命令</th><th>结果</th></tr></thead><tbody><tr><td><code>Xft.dpi</code></td><td><code>xrdb -query | grep -i dpi</code></td><td>无输出(未设置)</td></tr><tr><td>实际 DPI</td><td><code>xdpyinfo | grep -i resolution</code></td><td>92x94,约等于 96</td></tr><tr><td>GNOME 缩放</td><td><code>gsettings get org.gnome.desktop.interface scaling-factor</code></td><td>1</td></tr><tr><td>KDE 缩放</td><td><code>kreadconfig5 --file kdeglobals --group KScreen --key ScaleFactor</code></td><td>1</td></tr></tbody></table><p>注意:Plasma 5 用 <code>kreadconfig5</code>,Plasma 6 用 <code>kreadconfig6</code>。本机没有 <code>kreadconfig6</code>,所以是 Plasma 5。</p><p>结论:系统层面的缩放设置都是 1,问题不在用户设置里。</p><h3 id="_3-用框架的环境变量验证" tabindex="-1">3. 用框架的环境变量验证 <a class="header-anchor" href="#_3-用框架的环境变量验证" aria-label="Permalink to &quot;3. 用框架的环境变量验证&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GPUI_X11_SCALE_FACTOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pure-clash</span></span></code></pre></div><p>界面立刻恢复正常。这一步确认了:<strong>应用读到的缩放因子不是 1,但系统设置里并没有这个值。</strong></p><h2 id="原因分析" tabindex="-1">原因分析 <a class="header-anchor" href="#原因分析" aria-label="Permalink to &quot;原因分析&quot;">​</a></h2><blockquote><p>这一节的推断已经通过设置 <code>Xft.dpi: 96</code> 得到验证,见文末&quot;验证结果&quot;。</p></blockquote><p>GPUI 和 Slint(默认 winit 后端)在 X11 下取缩放因子的顺序大致是:</p><ol><li>框架自己的环境变量(<code>GPUI_X11_SCALE_FACTOR</code>、<code>WINIT_X11_SCALE_FACTOR</code>、<code>SLINT_SCALE_FACTOR</code>)</li><li><code>Xft.dpi</code>(XResources / XSETTINGS)</li><li>都没有时,用 RandR 里显示器的像素数和物理毫米数算 DPI,再除以 96</li></ol><p>本机 <code>Xft.dpi</code> 没有设置,所以落到了第 3 项。如果显示器(或转接线、KVM)通过 EDID 上报的物理尺寸偏小,算出的 DPI 就偏高,缩放因子大于 1,界面被放大。而 <code>xdpyinfo</code> 显示的 92x94 是 X 屏幕整体的值,和每个显示器上报的物理尺寸不一定一致,所以看上去&quot;一切正常&quot;。</p><p>这也解释了为什么两个不同的框架(GPUI 和 Slint)会同时出现同样的问题:它们共用同一套回退逻辑。</p><p>可以用下面的命令核对:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xrandr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connected</span></span></code></pre></div><p>输出里的 <code>344mm x 194mm</code> 这类数字就是上报的物理尺寸。用像素宽度除以(毫米数 / 25.4),如果算出来明显高于 96,就是这个原因。</p><h2 id="修复方法" tabindex="-1">修复方法 <a class="header-anchor" href="#修复方法" aria-label="Permalink to &quot;修复方法&quot;">​</a></h2><h3 id="方案-a-显式设置-xft-dpi-推荐-一次解决所有应用" tabindex="-1">方案 A:显式设置 <code>Xft.dpi</code>(推荐,一次解决所有应用) <a class="header-anchor" href="#方案-a-显式设置-xft-dpi-推荐-一次解决所有应用" aria-label="Permalink to &quot;方案 A:显式设置 \`Xft.dpi\`(推荐,一次解决所有应用)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Xft.dpi: 96&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.Xresources</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xrdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.Xresources</span></span></code></pre></div><p>已经运行的应用需要重新打开才生效,不需要重启系统。</p><p>如果重新登录后失效,说明 KDE 会话没有自动加载 <code>~/.Xresources</code>,有两个办法:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 办法 1:KDE 登录启动脚本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/plasma-workspace/env</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;xrdb -merge ~/.Xresources&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/plasma-workspace/env/xresources.sh</span></span></code></pre></div><p>办法 2:系统设置 → 外观 → 字体 → 勾选&quot;强制字体 DPI&quot;并设为 96(Plasma 5 的位置,不同版本菜单名可能略有差异)。办法 2 更省事。</p><h3 id="方案-b-给单个应用设环境变量-已验证对-gpui-有效" tabindex="-1">方案 B:给单个应用设环境变量(已验证对 GPUI 有效) <a class="header-anchor" href="#方案-b-给单个应用设环境变量-已验证对-gpui-有效" aria-label="Permalink to &quot;方案 B:给单个应用设环境变量(已验证对 GPUI 有效)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GPUI_X11_SCALE_FACTOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pure-clash</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SLINT_SCALE_FACTOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> your-app</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WINIT_X11_SCALE_FACTOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> your-app</span></span></code></pre></div><p><code>VAR=1 command</code> 只对这一次命令有效,不会写进当前 shell。想长期生效有三种方式:</p><p><strong>shell 别名</strong>(只对命令行启动有效):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;alias pure-clash=&#39;GPUI_X11_SCALE_FACTOR=1 pure-clash&#39;&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.zshrc</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.zshrc</span></span></code></pre></div><p><strong>修改 <code>.desktop</code> 文件</strong>(从应用菜单启动时生效):先复制到用户目录,避免软件更新时被覆盖,再把 <code>Exec=</code> 改成:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Exec=env GPUI_X11_SCALE_FACTOR=1 pure-clash</span></span></code></pre></div><p><strong>全局环境变量</strong>(所有 GPUI 应用都生效,包括 Zed,要留意影响范围),写入 <code>~/.config/plasma-workspace/env/gpui.sh</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GPUI_X11_SCALE_FACTOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p>重新登录后生效。变量支持小数,觉得界面偏小可以试 <code>1.25</code>。</p><h2 id="验证结果" tabindex="-1">验证结果 <a class="header-anchor" href="#验证结果" aria-label="Permalink to &quot;验证结果&quot;">​</a></h2><p>执行下面两条命令后,<strong>不需要重启系统</strong>,重新启动应用就恢复了正常缩放:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Xft.dpi: 96&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.Xresources</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xrdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.Xresources</span></span></code></pre></div><p>这说明原因确实是:X11 下没有设置 <code>Xft.dpi</code>,框架回退到用显示器上报的物理尺寸计算 DPI,算出了偏大的缩放因子。显式写入 <code>Xft.dpi</code> 之后,框架直接采用它,不再走回退逻辑。</p><p>两点补充:</p><ul><li><code>xrdb -merge</code> 是立即写入当前 X 会话的,只需要重新打开应用,不用重启系统。</li><li>这个设置只在当前登录会话有效。如果下次登录后又变大了,说明 KDE 没有自动加载 <code>~/.Xresources</code>,按上面&quot;方案 A&quot;里的办法 1 或办法 2 做持久化即可。</li></ul><p>没有再去核对 <code>xrandr</code> 里的物理尺寸,所以&quot;EDID 上报尺寸偏小&quot;这个具体细节只是最可能的解释,没有被单独证实。不过对修复来说,这一点已经不影响结论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>界面突然变大,先别只盯着桌面环境的缩放设置,GTK 变量对非 GTK 框架没用。</li><li>X11 下没有 <code>Xft.dpi</code> 时,很多框架会改用显示器物理尺寸算 DPI,EDID 数据不准就会放大。</li><li>排查顺序:<code>Xft.dpi</code> → 桌面环境缩放 → 框架环境变量 → <code>xrandr</code> 物理尺寸。</li><li>最稳妥的做法是显式写一个 <code>Xft.dpi</code>,不依赖自动检测。</li></ul>`,50)])])}const g=i(l,[["render",n]]);export{k as __pageData,g as default};
